package com.bank.eventpipe.ingest;

import com.bank.eventpipe.model.TradeEvent;
import java.util.*;
import java.util.logging.Logger;

// Partitioned durable log (Kafka-like): key by account → ordering per key, parallelism across keys.
public class EventLog {
    private static final Logger log = Logger.getLogger(EventLog.class.getName());
    private final int numPartitions;
    private final Map<Integer, List<TradeEvent>> partitions = new TreeMap<>();

    public EventLog(int numPartitions) {
        this.numPartitions = numPartitions;
        for (int i = 0; i < numPartitions; i++) partitions.put(i, new ArrayList<>());
    }

    public void append(TradeEvent e) {
        int p = Math.floorMod(e.getAccountId().hashCode(), numPartitions);
        partitions.get(p).add(e);
        log.fine(() -> "append " + e.getEventId() + " → partition " + p);
    }

    public Map<Integer, List<TradeEvent>> partitions() { return partitions; }
}
