package com.bank.eventpipe.process;

import com.bank.eventpipe.model.TradeEvent;
import com.bank.eventpipe.store.ColumnarSink;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Speed layer: react to each event immediately (fraud).
public class StreamingPath {
    private static final Logger log = Logger.getLogger(StreamingPath.class.getName());
    private final BigDecimal fraudThreshold;
    private final ColumnarSink sink;

    public StreamingPath(BigDecimal fraudThreshold, ColumnarSink sink) {
        this.fraudThreshold = fraudThreshold;
        this.sink = sink;
    }

    public void onEvent(TradeEvent e) {
        if (e.getAmount().compareTo(fraudThreshold) > 0) {
            log.severe(() -> "FRAUD ALERT: " + e.getAccountId() + " trade " + e.getAmount()
                    + " on " + e.getSymbol());
        }
        sink.upsert(e); // idempotent store keyed by eventId
    }
}
