package com.bank.eventpipe.process;

import com.bank.eventpipe.ingest.EventLog;
import com.bank.eventpipe.model.TradeEvent;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Batch layer: complete per-account totals over the whole day.
public class BatchPath {
    private static final Logger log = Logger.getLogger(BatchPath.class.getName());

    public Map<String, BigDecimal> dailyTotals(EventLog logStore) {
        log.info("BATCH: computing complete per-account totals");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (List<TradeEvent> part : logStore.partitions().values()) {
            for (TradeEvent e : part) totals.merge(e.getAccountId(), e.getAmount(), BigDecimal::add);
        }
        return totals;
    }
}
