package com.bank.eventpipe.store;

import com.bank.eventpipe.model.TradeEvent;
import java.util.*;
import java.util.logging.Logger;

// Columnar store (Parquet/Iceberg-like): idempotent upsert by eventId.
public class ColumnarSink {
    private static final Logger log = Logger.getLogger(ColumnarSink.class.getName());
    private final Map<String, TradeEvent> stored = new LinkedHashMap<>();

    public void upsert(TradeEvent e) {
        stored.put(e.getEventId(), e); // replay-safe: same key overwrites, never duplicates
    }
    public int size() { return stored.size(); }
}
