package com.bank.eventpipe;

import com.bank.eventpipe.ingest.EventLog;
import com.bank.eventpipe.model.TradeEvent;
import com.bank.eventpipe.process.*;
import com.bank.eventpipe.store.ColumnarSink;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class PipelineDesignDemo {
    private static final Logger log = Logger.getLogger(PipelineDesignDemo.class.getName());

    public static void main(String[] args) {
        EventLog logStore = new EventLog(12);
        List<TradeEvent> events = List.of(
            new TradeEvent("E1", "SAV2001", "RELIANCE", new BigDecimal("1200.00")),
            new TradeEvent("E2", "SAV2001", "TCS", new BigDecimal("150000.00")),
            new TradeEvent("E3", "CUR3001", "INFY", new BigDecimal("5000.00")),
            new TradeEvent("E4", "CUR3001", "HDFC", new BigDecimal("250000.00"))
        );

        log.info("=== INGEST into partitioned log (keyed by account) ===");
        events.forEach(logStore::append);

        ColumnarSink sink = new ColumnarSink();
        StreamingPath stream = new StreamingPath(new BigDecimal("100000.00"), sink);
        log.info("=== STREAMING PATH (immediate fraud) ===");
        events.forEach(stream::onEvent);

        log.info("=== REPLAY (prove idempotent storage) ===");
        events.forEach(stream::onEvent);
        log.info("Sink size after replay = " + sink.size());

        log.info("=== BATCH PATH (complete daily totals) ===");
        new BatchPath().dailyTotals(logStore).forEach((acc, total) ->
            log.info("DAILY total " + acc + " = " + total));
    }
}
